const sat16 = (s) => Math.max(-32768, Math.min(32767, s));
const q = (h) => h / 256;
const x = 32000, v = 1000;
const contact = (A, B) => { const d = Math.floor((B - A) / 2); return [A + d, B - d]; };
const r = {
  particle: { x: q(x), v: q(v), raw: x + v, sat: sat16(x + v), satQ: q(sat16(x + v)) },
  contactExtreme: contact(32767, -32768),
  contactSmall: contact(-3, 4),
  breakEvenVsAosScalar: 2076.3333333333335 / (1516.7916666666665 - 150.375),
  breakEvenVsAosPie: 2076.3333333333335 / (1002.4583333333333 - 150.375),
  wrapperCycles: 179.125 - 150.375,
  pieTrips128: 128 / 8,
  contactTrips: [57, 41, 30].map(b => Math.floor(b / 8)),
  contactTail: [57, 41, 30].map(b => b % 8),
  rows: 5 * 12 * 12 + 7 * 14
};
